pub mod encoding;
pub mod url;

pub use encoding::{url_decode, url_encode};
pub use url::Url;

//! Percent-encoding helpers operating on raw bytes.

const HEX: &[u8; 16] = b"0123456789abcdef";

fn is_unreserved(b: u8) -> bool {
    matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~')
}

/// Percent-encode every byte that is not an unreserved character.
/// Output is pure ASCII using lowercase hex digits.
pub fn url_encode(input: &[u8]) -> String {
    let mut out = String::with_capacity(input.len());
    for &b in input {
        if is_unreserved(b) {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0f) as usize] as char);
        }
    }
    out
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

/// Decode a percent-encoded byte string.
/// `+` becomes a space; `%XX` (case-insensitive hex) becomes the byte;
/// a `%` not followed by two hex digits is kept literally.
pub fn url_decode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(input.len());
    let mut i = 0;
    while i < input.len() {
        match input[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' => {
                let hi = input.get(i + 1).and_then(|&b| hex_val(b));
                let lo = input.get(i + 2).and_then(|&b| hex_val(b));
                match (hi, lo) {
                    (Some(h), Some(l)) => {
                        out.push((h << 4) | l);
                        i += 3;
                    }
                    _ => {
                        out.push(b'%');
                        i += 1;
                    }
                }
            }
            b => {
                out.push(b);
                i += 1;
            }
        }
    }
    out
}

//! Minimal URL parsing matching the interface of the C++ `url_parser::URL`.

/// A parsed URL with scheme, host, path and query components.
pub struct Url {
    scheme: String,
    host: String,
    path: String,
    query: String,
}

impl Url {
    pub fn new(input: &str) -> Url {
        // Split off the scheme ("scheme://...").
        let (scheme, rest) = match input.find("://") {
            Some(i) => (&input[..i], &input[i + 3..]),
            None => ("", input),
        };

        // Host runs until the first '/', '?' or '#'.
        let host_end = rest
            .find(|c| c == '/' || c == '?' || c == '#')
            .unwrap_or(rest.len());
        let host = &rest[..host_end];
        let after_host = &rest[host_end..];

        // Path runs until '?' (query) or '#' (fragment).
        let (path, after_path) = match after_host.find(|c| c == '?' || c == '#') {
            Some(i) => (&after_host[..i], &after_host[i..]),
            None => (after_host, ""),
        };

        // Query is everything between '?' and '#'.
        let query = if let Some(stripped) = after_path.strip_prefix('?') {
            match stripped.find('#') {
                Some(i) => &stripped[..i],
                None => stripped,
            }
        } else {
            ""
        };

        Url {
            scheme: scheme.to_string(),
            host: host.to_string(),
            path: path.to_string(),
            query: query.to_string(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    /// Split the query string into raw (still percent-encoded) key/value pairs.
    pub fn query_params(&self) -> Vec<(String, String)> {
        let mut params = Vec::new();
        if self.query.is_empty() {
            return params;
        }
        for pair in self.query.split('&') {
            match pair.split_once('=') {
                Some((k, v)) => params.push((k.to_string(), v.to_string())),
                None => params.push((pair.to_string(), String::new())),
            }
        }
        params
    }
}

mod url_parser;

use std::io::Write;

#[cfg(unix)]
fn arg_bytes(arg: &std::ffi::OsStr) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    arg.as_bytes().to_vec()
}

#[cfg(not(unix))]
fn arg_bytes(arg: &std::ffi::OsStr) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let input = arg_bytes(&args[1]);

    let encoded = url_parser::url_encode(&input);
    let decoded = url_parser::url_decode(&input);

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    out.write_all(encoded.as_bytes()).unwrap();
    out.write_all(b"\n").unwrap();
    out.write_all(&decoded).unwrap();
    out.write_all(b"\n").unwrap();

    let url = format!("http://example.com/test?q={}", encoded);
    let parser = url_parser::Url::new(&url);

    out.write_all(parser.scheme().as_bytes()).unwrap();
    out.write_all(b"\n").unwrap();
    out.write_all(parser.host().as_bytes()).unwrap();
    out.write_all(b"\n").unwrap();
    out.write_all(parser.path().as_bytes()).unwrap();
    out.write_all(b"\n").unwrap();
    out.write_all(parser.query().as_bytes()).unwrap();
    out.write_all(b"\n").unwrap();

    for (key, value) in parser.query_params() {
        out.write_all(&url_parser::url_decode(key.as_bytes())).unwrap();
        out.write_all(b"\n").unwrap();
        out.write_all(&url_parser::url_decode(value.as_bytes())).unwrap();
        out.write_all(b"\n").unwrap();
    }
}

