pub fn query_params(&self) -> Vec<(Vec<u8>, Vec<u8>)> {
    let mut params = Vec::new();
    if self.query.is_empty() {
        return params;
    }
    for pair in self.query.split('&') {
        match pair.split_once('=') {
            Some((k, v)) => params.push((
                crate::url_parser::url_decode(k.as_bytes()),
                crate::url_parser::url_decode(v.as_bytes()),
            )),
            None => params.push((crate::url_parser::url_decode(pair.as_bytes()), Vec::new())),
        }
    }
    params
}

